import { existsSync } from "node:fs";
import { mkdir, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import type { AppPaths } from "../paths";
import { git } from "./git";

/**
 * The work substrate (decision D-8): crewmates operate on git repos,
 * worktree per task. Repo-less tasks land in the app-managed default
 * local-only repo (git init on first use), so every crewmate has a real,
 * versioned cwd. Phase 3 adds the user-registered repo registry on top.
 */

export type TaskWorkspace = {
  taskId: string;
  /** The worktree the crewmate runs in. */
  cwd: string;
  branch: string;
  /** The repo the worktree belongs to. */
  repoDir: string;
};

export class WorkspaceService {
  constructor(private readonly paths: AppPaths) {}

  /** Lazily creates the default local-only repo with an initial commit. */
  async ensureDefaultRepo(): Promise<string> {
    const dir = this.paths.defaultWorkspaceDir;
    if (!existsSync(join(dir, ".git"))) {
      await mkdir(dir, { recursive: true });
      await git(dir, ["init", "--initial-branch=main"]);
      await git(dir, ["config", "user.name", "Firstmate 3000"]);
      await git(dir, ["config", "user.email", "firstmate@localhost"]);
      await writeFile(
        join(dir, "README.md"),
        "# Firstmate workspace\n\nThe app-managed default workspace. Tasks not tied to a registered repo run here, one git worktree per task.\n",
      );
      await git(dir, ["add", "-A"]);
      await git(dir, ["commit", "-m", "chore: initialize default workspace"]);
    }
    return dir;
  }

  /** Creates the task's worktree on branch fm/task-<id>. */
  async createTaskWorktree(taskId: string, repoDir?: string): Promise<TaskWorkspace> {
    const repo = repoDir ?? (await this.ensureDefaultRepo());
    const cwd = join(this.paths.worktreesDir, taskId);
    const branch = `fm/task-${taskId}`;
    await mkdir(this.paths.worktreesDir, { recursive: true });
    await git(repo, ["worktree", "add", "-b", branch, cwd]);
    return { taskId, cwd, branch, repoDir: repo };
  }

  /**
   * Lands a finished task's branch into the branch currently checked out in
   * its repo (captain decision Q5). Deliberately forge-agnostic: pure local
   * git - fast-forward when possible, a merge commit otherwise - and never
   * a forge API, so GitHub, GitLab, Bitbucket, and plain remotes are all
   * equal. Refuses loudly (with the concrete reason) on a dirty repo, a
   * detached HEAD, or a merge conflict; a refused conflict is aborted so
   * the repo is left exactly as found.
   */
  async landTaskWork(workspace: TaskWorkspace): Promise<{ mode: "fast-forward" | "merge" }> {
    const { repoDir, branch } = workspace;
    const dirty = await git(repoDir, ["status", "--porcelain"]);
    if (dirty) {
      throw new Error("The repository has uncommitted changes; commit or stash them first.");
    }
    let current: string;
    try {
      current = await git(repoDir, ["symbolic-ref", "--short", "HEAD"]);
    } catch {
      throw new Error("The repository is on a detached HEAD; check out a branch first.");
    }
    try {
      await git(repoDir, ["merge", "--ff-only", branch]);
      return { mode: "fast-forward" };
    } catch {
      // Fall through to a real merge commit.
    }
    try {
      await git(repoDir, ["merge", "--no-ff", "--no-edit", branch]);
      return { mode: "merge" };
    } catch (caught) {
      await git(repoDir, ["merge", "--abort"]).catch(() => {});
      const message = caught instanceof Error ? caught.message : String(caught);
      throw new Error(
        `Merging ${branch} into ${current} hit a conflict; resolve it manually. ${firstGitError(message)}`,
      );
    }
  }

  /**
   * What a discard would destroy: uncommitted edits in the worktree plus
   * branch commits not reachable from the repo's checked-out HEAD. A missing
   * worktree or branch counts as nothing to lose - there is nothing left to
   * protect, and discard must still be able to clean up the bookkeeping.
   */
  async taskWorkStatus(workspace: TaskWorkspace): Promise<{
    dirty: boolean;
    unlandedCommits: number;
  }> {
    let dirty = false;
    let unlandedCommits = 0;
    try {
      dirty = (await git(workspace.cwd, ["status", "--porcelain"])) !== "";
    } catch {
      // Worktree already gone.
    }
    try {
      const count = await git(workspace.repoDir, [
        "rev-list",
        "--count",
        workspace.branch,
        "--not",
        "HEAD",
      ]);
      unlandedCommits = Number.parseInt(count, 10) || 0;
    } catch {
      // Branch already gone.
    }
    return { dirty, unlandedCommits };
  }

  /**
   * Removes a task's worktree and branch (decision D-13: a task's workspace
   * dies with it). The repo itself and anything merged from the branch stay.
   */
  async removeTaskWorktree(workspace: TaskWorkspace): Promise<void> {
    try {
      await git(workspace.repoDir, ["worktree", "remove", "--force", workspace.cwd]);
    } catch {
      // The worktree dir may already be gone; prune bookkeeping either way.
      await rm(workspace.cwd, { recursive: true, force: true });
      await git(workspace.repoDir, ["worktree", "prune"]);
    }
    try {
      await git(workspace.repoDir, ["branch", "-D", workspace.branch]);
    } catch {
      // Branch already gone.
    }
  }
}

/** The first stderr-ish line of a git failure, for a card-sized reason. */
function firstGitError(message: string): string {
  const line = message
    .split("\n")
    .map((entry) => entry.trim())
    .find((entry) => entry.startsWith("CONFLICT") || entry.startsWith("error:"));
  return line ?? "";
}

import { existsSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { appPathsFor } from "../paths";
import { git } from "./git";
import { WorkspaceService } from "./workspaceService";

function service() {
  const userData = mkdtempSync(join(tmpdir(), "fm3000-ws-"));
  const paths = appPathsFor(userData);
  return { paths, workspace: new WorkspaceService(paths) };
}

describe("WorkspaceService", () => {
  it("initializes the default repo lazily with an initial commit", async () => {
    const { paths, workspace } = service();
    expect(existsSync(paths.defaultWorkspaceDir)).toBe(false);
    const repo = await workspace.ensureDefaultRepo();
    expect(repo).toBe(paths.defaultWorkspaceDir);
    expect(await git(repo, ["rev-parse", "--abbrev-ref", "HEAD"])).toBe("main");
    expect(await git(repo, ["log", "--oneline"])).toContain("initialize default workspace");
    // Idempotent.
    await workspace.ensureDefaultRepo();
    expect((await git(repo, ["log", "--oneline"])).split("\n")).toHaveLength(1);
  });

  it("creates one worktree per task on its own branch", async () => {
    const { paths, workspace } = service();
    const a = await workspace.createTaskWorktree("aaaa1111");
    const b = await workspace.createTaskWorktree("bbbb2222");
    expect(a.cwd).toBe(join(paths.worktreesDir, "aaaa1111"));
    expect(a.branch).toBe("fm/task-aaaa1111");
    expect(await git(a.cwd, ["rev-parse", "--abbrev-ref", "HEAD"])).toBe("fm/task-aaaa1111");
    expect(await git(b.cwd, ["rev-parse", "--abbrev-ref", "HEAD"])).toBe("fm/task-bbbb2222");
    // Both worktrees share the default repo.
    const list = await git(paths.defaultWorkspaceDir, ["worktree", "list"]);
    expect(list).toContain("aaaa1111");
    expect(list).toContain("bbbb2222");
  });

  it("removes a task's worktree and branch on deletion", async () => {
    const { paths, workspace } = service();
    const ws = await workspace.createTaskWorktree("cccc3333");
    expect(existsSync(ws.cwd)).toBe(true);
    await workspace.removeTaskWorktree(ws);
    expect(existsSync(ws.cwd)).toBe(false);
    const branches = await git(paths.defaultWorkspaceDir, ["branch", "--list", "fm/task-cccc3333"]);
    expect(branches).toBe("");
  });
});

describe("taskWorkStatus (P1: what a discard would destroy)", () => {
  it("reports a fresh task as clean", async () => {
    const { workspace } = service();
    const task = await workspace.createTaskWorktree("stat1111");
    expect(await workspace.taskWorkStatus(task)).toEqual({ dirty: false, unlandedCommits: 0 });
  });

  it("counts unlanded commits and sees uncommitted edits", async () => {
    const { workspace } = service();
    const task = await workspace.createTaskWorktree("stat2222");
    writeFileSync(join(task.cwd, "a.txt"), "one\n");
    await git(task.cwd, ["add", "-A"]);
    await git(task.cwd, ["commit", "-m", "feat: one"]);
    writeFileSync(join(task.cwd, "b.txt"), "wip\n");
    expect(await workspace.taskWorkStatus(task)).toEqual({ dirty: true, unlandedCommits: 1 });
  });

  it("treats landed commits as safe again", async () => {
    const { workspace } = service();
    const task = await workspace.createTaskWorktree("stat3333");
    writeFileSync(join(task.cwd, "a.txt"), "one\n");
    await git(task.cwd, ["add", "-A"]);
    await git(task.cwd, ["commit", "-m", "feat: one"]);
    await workspace.landTaskWork(task);
    expect(await workspace.taskWorkStatus(task)).toEqual({ dirty: false, unlandedCommits: 0 });
  });

  it("reports nothing to lose when the worktree is already gone", async () => {
    const { workspace } = service();
    const task = await workspace.createTaskWorktree("stat4444");
    await workspace.removeTaskWorktree(task);
    expect(await workspace.taskWorkStatus(task)).toEqual({ dirty: false, unlandedCommits: 0 });
  });
});

describe("landTaskWork (Q5, forge-agnostic local landing)", () => {
  it("fast-forwards a clean branch and reports the mode", async () => {
    const { workspace } = service();
    const task = await workspace.createTaskWorktree("land1111");
    writeFileSync(join(task.cwd, "feature.txt"), "done\n");
    await git(task.cwd, ["add", "-A"]);
    await git(task.cwd, ["commit", "-m", "feat: land me"]);

    const result = await workspace.landTaskWork(task);
    expect(result.mode).toBe("fast-forward");
    expect(await git(task.repoDir, ["log", "--oneline", "-1"])).toContain("feat: land me");

    await workspace.removeTaskWorktree(task);
    expect(existsSync(task.cwd)).toBe(false);
  });

  it("falls back to a merge commit when main moved on", async () => {
    const { workspace } = service();
    const task = await workspace.createTaskWorktree("land2222");
    writeFileSync(join(task.cwd, "feature.txt"), "done\n");
    await git(task.cwd, ["add", "-A"]);
    await git(task.cwd, ["commit", "-m", "feat: branch work"]);
    // Main advances independently on a different file.
    writeFileSync(join(task.repoDir, "elsewhere.txt"), "moved\n");
    await git(task.repoDir, ["add", "-A"]);
    await git(task.repoDir, ["commit", "-m", "chore: mainline moved"]);

    const result = await workspace.landTaskWork(task);
    expect(result.mode).toBe("merge");
    const log = await git(task.repoDir, ["log", "--oneline", "-3"]);
    expect(log).toContain("feat: branch work");
    expect(log).toContain("chore: mainline moved");
  });

  it("refuses a conflict and leaves the repo exactly as found", async () => {
    const { workspace } = service();
    const task = await workspace.createTaskWorktree("land3333");
    writeFileSync(join(task.cwd, "README.md"), "branch version\n");
    await git(task.cwd, ["add", "-A"]);
    await git(task.cwd, ["commit", "-m", "feat: branch readme"]);
    writeFileSync(join(task.repoDir, "README.md"), "main version\n");
    await git(task.repoDir, ["add", "-A"]);
    await git(task.repoDir, ["commit", "-m", "chore: main readme"]);
    const headBefore = await git(task.repoDir, ["rev-parse", "HEAD"]);

    await expect(workspace.landTaskWork(task)).rejects.toThrow(/conflict/);
    expect(await git(task.repoDir, ["rev-parse", "HEAD"])).toBe(headBefore);
    expect(await git(task.repoDir, ["status", "--porcelain"])).toBe("");
  });

  it("refuses a dirty repository before touching anything", async () => {
    const { workspace } = service();
    const task = await workspace.createTaskWorktree("land4444");
    writeFileSync(join(task.repoDir, "wip.txt"), "uncommitted\n");
    await expect(workspace.landTaskWork(task)).rejects.toThrow(/uncommitted changes/);
  });
});

