  /** Dispatch one queued row through the shared start path. */
  async dispatchQueuedTask(taskId: string, options: { ignoreAsk?: boolean } = {}): Promise<void> {
    const record = this.options.tasks.get(taskId);
    if (record?.status !== "open" || record.kind !== "work") return;
    const gate = record.gate;
    const blockers = this.options.tasks.blockers(taskId);
    try {
      const routed = this.options.router?.decide(
        taskId,
        record.prompt,
        record.difficulty ?? undefined,
      );
      if (!options.ignoreAsk && record.difficulty && routed && cannotServeAsk(routed)) {
        // The explicit reasoning ask still cannot be served when the gate
        // clears: re-gate behind the same decision card instead of quietly
        // starting lower (P7) - the commission-time protection, applied at
        // dispatch too. "Start anyway" on the card passes ignoreAsk.
        this.options.tasks.setGate(
          taskId,
          {
            kind: "captain",
            ref: "reasoning-wait",
            reason: `no ${routed.bucket} model has quota`,
          },
          `held: no ${routed.bucket} model has quota`,
        );
        this.addReasoningWaitCard(taskId, record.title, routed.bucket, routed.servedBucket);
        this.broadcastCrewCounts();
        return;
      }
      // The briefing consult (contract v1, spec 4.3): a queued row's stored
      // intent is expanded into a full brief at gate-open, recorded before
      // the crewmate starts. The intent template always rides along so the
      // user's verbatim words reach the crewmate regardless; on consult
      // failure the intent alone is delivered and the crewmate self-briefs.
      let brief = record.prompt;
      if (this.options.briefingConsult) {
        const expanded = await this.options.briefingConsult(record.prompt, record.repoId);
        if (expanded) {
          brief = `${expanded}\n\n---\n\nThe structured intent this brief expands (its verbatim user words outrank the brief above):\n\n${record.prompt}`;
          this.options.tasks.setPrompt(taskId, brief);
        }
      }
      await this.startTask({
        taskId,
        title: record.title,
        brief,
        repoId: record.repoId,
        routed,
        fresh: false,
      });
      const because = gate
        ? gateClearedText(gate)
        : blockers.length > 0
          ? `${blockers.map((blocker) => `task ${blocker.id}`).join(" and ")} finished`
          : undefined;
      this.options.broadcastEvent({
        type: "firstmate_note",
        text: `starting "${record.title}"${because ? ` - ${because}` : ""}.`,
      });
      this.routeCrewEvent(
        taskId,
        `[fm-op] queued task ${taskId} "${record.title}" started - its wait ended.`,
      );
    } catch (caught) {
      const message = caught instanceof Error ? caught.message : String(caught);
      this.routeCrewEvent(
        taskId,
        `[fm-op] queued task ${taskId} "${record.title}" could not start: ${capWithOverflow(message, "queue-start-failure")}`,
      );
    }
    this.broadcastCrewCounts();
  }

