/**
 * Creates the task's worktree on branch fm/task-<id>. Idempotent: a retry
 * reuses an existing matching worktree, or checks out an existing branch
 * without `-b`, so a leftover from a failed or overlapping start never
 * fails with "branch already exists".
 */
async createTaskWorktree(taskId: string, repoDir?: string): Promise<TaskWorkspace> {
  const repo = repoDir ?? (await this.ensureDefaultRepo());
  const cwd = join(this.paths.worktreesDir, taskId);
  const branch = `fm/task-${taskId}`;
  await mkdir(this.paths.worktreesDir, { recursive: true });
  await git(repo, ["worktree", "prune"]);
  if (await isMatchingWorktree(cwd, branch)) {
    return { taskId, cwd, branch, repoDir: repo };
  }
  if (existsSync(cwd)) {
    if (await isGitRepo(cwd)) {
      throw new Error(
        `Worktree path ${cwd} exists but is not on ${branch}; refuse to reuse it.`,
      );
    }
    await rm(cwd, { recursive: true, force: true });
  }
  if (await branchExists(repo, branch)) {
    await git(repo, ["worktree", "add", cwd, branch]);
  } else {
    await git(repo, ["worktree", "add", "-b", branch, cwd]);
  }
  return { taskId, cwd, branch, repoDir: repo };
}

async function isMatchingWorktree(cwd: string, branch: string): Promise<boolean> {
  if (!existsSync(cwd)) return false;
  try {
    return (await git(cwd, ["rev-parse", "--abbrev-ref", "HEAD"])) === branch;
  } catch {
    return false;
  }
}

async function branchExists(repo: string, branch: string): Promise<boolean> {
  try {
    await git(repo, ["show-ref", "--verify", "--quiet", `refs/heads/${branch}`]);
    return true;
  } catch {
    return false;
  }
}

